INSERT INTO compact_binding_guard SELECT IF(DATABASE() IS NOT NULL AND BINARY DATABASE()<>BINARY '__SOURCE_SCHEMA__' AND @@FOREIGN_KEY_CHECKS=1 AND @@SESSION.sql_mode REGEXP '(^|,)(STRICT_TRANS_TABLES|STRICT_ALL_TABLES)(,|$)',1,0);
INSERT INTO compact_binding_guard SELECT IF(REGEXP_LIKE('__SOURCE_BINDING_OFFSET__','^[+-][0-9]{2}:[0-9]{2}$','c') AND CONVERT_TZ('2026-01-01','__SOURCE_BINDING_OFFSET__','+00:00') IS NOT NULL,1,0);
INSERT INTO compact_binding_guard SELECT IF(COUNT(DISTINCT privilege_type)=2,1,0) FROM information_schema.schema_privileges WHERE BINARY table_schema=BINARY '__SOURCE_SCHEMA__' AND privilege_type IN ('SELECT','TRIGGER') AND grantee=CONCAT(QUOTE(SUBSTRING_INDEX(CURRENT_USER(),'@',1)),'@',QUOTE(SUBSTRING_INDEX(CURRENT_USER(),'@',-1)));
INSERT INTO compact_binding_guard SELECT IF(COUNT(*)=1,1,0) FROM information_schema.tables WHERE BINARY table_schema=BINARY '__SOURCE_SCHEMA__' AND BINARY table_name=BINARY 'organization_binding_audit' AND table_type='BASE TABLE' AND engine='InnoDB' AND table_collation='utf8mb4_unicode_ci';
INSERT INTO compact_binding_columns VALUES
('id','1','bigint','NO',NULL,NULL,'auto_increment'),
('user_id','2','bigint','NO',NULL,NULL,''),
('username','3','varchar(50)','NO','utf8mb4_unicode_ci',NULL,''),
('actor_user_id','4','bigint','NO',NULL,NULL,''),
('actor_username','5','varchar(50)','NO','utf8mb4_unicode_ci',NULL,''),
('before_employee_id','6','bigint','YES',NULL,NULL,''),
('after_employee_id','7','bigint','YES',NULL,NULL,''),
('binding_version','8','int','NO',NULL,NULL,''),
('action','9','varchar(16)','NO','utf8mb4_unicode_ci',NULL,''),
('created_at','10','datetime','NO',NULL,NULL,'');
INSERT INTO compact_binding_guard SELECT IF(COUNT(*)=0,1,0) FROM information_schema.columns c LEFT JOIN compact_binding_columns e ON BINARY e.column_name=BINARY c.column_name WHERE BINARY c.table_schema=BINARY '__SOURCE_SCHEMA__' AND BINARY c.table_name=BINARY 'organization_binding_audit' AND e.column_name IS NULL;
INSERT INTO compact_binding_guard SELECT IF(COUNT(*)=0,1,0) FROM compact_binding_columns e LEFT JOIN information_schema.columns c ON BINARY c.table_schema=BINARY '__SOURCE_SCHEMA__' AND BINARY c.table_name=BINARY 'organization_binding_audit' AND BINARY c.column_name=BINARY e.column_name WHERE c.column_name IS NULL OR NOT(c.ordinal_position<=>e.ordinal_position) OR NOT(BINARY LOWER(c.column_type)<=>BINARY e.column_type) OR NOT(BINARY c.is_nullable<=>BINARY e.nullable) OR NOT(BINARY c.collation_name<=>BINARY e.collation_name) OR NOT(BINARY c.column_default<=>BINARY e.default_value) OR NOT(BINARY LOWER(c.extra)<=>BINARY e.extra) OR NOT(BINARY c.generation_expression<=>BINARY '');
INSERT INTO compact_binding_guard SELECT IF(COUNT(*)=0,1,0) FROM information_schema.triggers WHERE BINARY event_object_schema=BINARY '__SOURCE_SCHEMA__' AND BINARY event_object_table=BINARY 'organization_binding_audit';
INSERT INTO compact_binding_guard SELECT IF(COUNT(*)=0,1,0) FROM information_schema.table_constraints WHERE BINARY table_schema=BINARY '__SOURCE_SCHEMA__' AND BINARY table_name=BINARY 'organization_binding_audit' AND constraint_type IN ('FOREIGN KEY','CHECK');
INSERT INTO compact_binding_guard SELECT IF(COUNT(*)=1 AND COALESCE(SUM(BINARY index_name=BINARY 'PRIMARY' AND BINARY column_name=BINARY 'id' AND seq_in_index=1 AND sub_part IS NULL AND index_type='BTREE' AND is_visible='YES'),0)=1,1,0) FROM information_schema.statistics WHERE BINARY table_schema=BINARY '__SOURCE_SCHEMA__' AND BINARY table_name=BINARY 'organization_binding_audit' AND non_unique=0;
INSERT INTO compact_binding_guard SELECT IF(COUNT(*)=0,1,0) FROM audit_event WHERE kind='ORGANIZATION_BINDING' OR legacy_source='organization_binding_audit';
INSERT INTO compact_binding_guard SELECT IF(COUNT(*)=0,1,0) FROM `__SOURCE_SCHEMA__`.organization_binding_audit s WHERE NOT COALESCE(((s.user_id>0) AND (s.actor_user_id>0) AND (CHAR_LENGTH(s.username) BETWEEN 1 AND 50) AND (CHAR_LENGTH(s.actor_username) BETWEEN 1 AND 50) AND (s.binding_version BETWEEN 1 AND 2147483647) AND ((s.before_employee_id IS NULL OR s.before_employee_id>0)) AND ((s.after_employee_id IS NULL OR s.after_employee_id>0)) AND (NOT(s.before_employee_id<=>s.after_employee_id)) AND (((BINARY s.action=BINARY 'BIND' AND s.before_employee_id IS NULL AND s.after_employee_id IS NOT NULL) OR (BINARY s.action=BINARY 'UNBIND' AND s.before_employee_id IS NOT NULL AND s.after_employee_id IS NULL) OR (BINARY s.action=BINARY 'REBIND' AND s.before_employee_id IS NOT NULL AND s.after_employee_id IS NOT NULL))) AND (CONVERT_TZ(s.created_at,'__SOURCE_BINDING_OFFSET__','+00:00') IS NOT NULL) AND (TIMESTAMPDIFF(SECOND,CONVERT_TZ(s.created_at,'__SOURCE_BINDING_OFFSET__','+00:00'),s.created_at)=(IF(LEFT('__SOURCE_BINDING_OFFSET__',1)='-',-1,1)*(CAST(SUBSTRING('__SOURCE_BINDING_OFFSET__',2,2) AS SIGNED)*3600+CAST(SUBSTRING('__SOURCE_BINDING_OFFSET__',5,2) AS SIGNED)*60)))),FALSE);
INSERT INTO audit_event(event_id,kind,owner_user_id,actor_user_id,resource_type,resource_id,action,revision,occurred_at,payload_version,payload_json,legacy_source,legacy_key) SELECT CONCAT('legacy-binding-',s.id),'ORGANIZATION_BINDING',s.user_id,s.actor_user_id,'USER',CAST(s.user_id AS CHAR),s.action,s.binding_version,CONVERT_TZ(s.created_at,'__SOURCE_BINDING_OFFSET__','+00:00'),1,JSON_OBJECT('username',s.username,'actorUsername',s.actor_username,'beforeEmployeeId',s.before_employee_id,'afterEmployeeId',s.after_employee_id,'legacyId',CAST(s.id AS CHAR),'legacyCreatedAt',DATE_FORMAT(s.created_at,'%Y-%m-%d %H:%i:%s.%f')),'organization_binding_audit',CAST(s.id AS CHAR) FROM `__SOURCE_SCHEMA__`.organization_binding_audit s ORDER BY s.id;
INSERT INTO compact_binding_guard SELECT IF((SELECT COUNT(*) FROM audit_event WHERE kind='ORGANIZATION_BINDING')=(SELECT COUNT(*) FROM `__SOURCE_SCHEMA__`.organization_binding_audit),1,0);
INSERT INTO compact_binding_guard SELECT IF(COUNT(*)=0,1,0) FROM `__SOURCE_SCHEMA__`.organization_binding_audit s LEFT JOIN audit_event t ON BINARY t.legacy_source=BINARY 'organization_binding_audit' AND BINARY t.legacy_key=BINARY CAST(s.id AS CHAR) WHERE t.id IS NULL OR NOT(BINARY t.legacy_source<=>BINARY 'organization_binding_audit') OR NOT(BINARY t.legacy_key<=>BINARY CAST(s.id AS CHAR)) OR NOT(BINARY t.event_id<=>BINARY CONCAT('legacy-binding-',s.id)) OR NOT(BINARY t.kind<=>BINARY 'ORGANIZATION_BINDING') OR NOT(t.owner_user_id<=>s.user_id) OR NOT(t.actor_user_id<=>s.actor_user_id) OR NOT(BINARY t.resource_type<=>BINARY 'USER') OR NOT(BINARY t.resource_id<=>BINARY CAST(s.user_id AS CHAR)) OR NOT(BINARY t.action<=>BINARY s.action) OR NOT(t.revision<=>s.binding_version) OR NOT(t.occurred_at<=>CONVERT_TZ(s.created_at,'__SOURCE_BINDING_OFFSET__','+00:00')) OR NOT(t.payload_version<=>1) OR NOT(BINARY t.payload_json<=>BINARY JSON_OBJECT('username',s.username,'actorUsername',s.actor_username,'beforeEmployeeId',s.before_employee_id,'afterEmployeeId',s.after_employee_id,'legacyId',CAST(s.id AS CHAR),'legacyCreatedAt',DATE_FORMAT(s.created_at,'%Y-%m-%d %H:%i:%s.%f'))) OR NOT(t.detection_model_id IS NULL) OR NOT(t.session_id IS NULL) OR NOT(t.message_id IS NULL) OR NOT(t.run_id IS NULL) OR NOT(t.journal_run_id IS NULL) OR NOT(t.sequence_no IS NULL) OR NOT(t.request_id IS NULL) OR NOT(t.content_sha256 IS NULL) OR NOT(t.previous_sha256 IS NULL) OR NOT(t.event_sha256 IS NULL) OR NOT(t.quantity IS NULL) OR NOT(t.unit IS NULL) OR NOT(t.request_scope IS NULL) OR NOT(t.policy_version IS NULL) OR NOT(t.outcome IS NULL) OR NOT(t.observed_at IS NULL);
