-- Organization binding audit copy candidate, NOT EXECUTED. Source: actual V20, ten columns.
-- Render distinct source schema and the evidenced fixed source UTC offset; keep the source stopped.
-- Target baseline already exists. This kind/provenance must be empty; other domains are retained.
-- Stop on the first error and ROLLBACK on this same connection. Never --force.
-- No source UPDATE/DELETE/DROP. Original IDs/timestamps remain immutable evidence, not new cursor IDs.
SET NAMES utf8mb4;
CREATE TEMPORARY TABLE compact_binding_guard(valid INT NOT NULL CHECK(valid=1)) ENGINE=InnoDB;
CREATE TEMPORARY TABLE compact_binding_columns(column_name VARCHAR(64),ordinal_position INT,column_type VARCHAR(64),nullable VARCHAR(3),collation_name VARCHAR(64),default_value VARCHAR(64),extra VARCHAR(64),PRIMARY KEY(column_name)) ENGINE=InnoDB;
START TRANSACTION;
COMMIT;
DROP TEMPORARY TABLE compact_binding_columns;
DROP TEMPORARY TABLE compact_binding_guard;
